namespace ID_Indetails.api.DTO.Request.Setup;

/// <summary>
/// The first super admin. Their name is required up front because active accounts must have
/// one; the password is generated by the server and emailed to them.
/// </summary>
public sealed record CreateSuperAdminRequest
{
    public string Email { get; init; } = string.Empty;

    public string FirstName { get; init; } = string.Empty;

    public string LastName { get; init; } = string.Empty;

    public string? Position { get; init; }
}
